mapper.select:
SELECT id, answer_sheet_id, question_no, provider_name, protocol, model, reference_answer, recognized_text, suggested_score, confidence, judge_reason, status, error_message, raw_response, create_time FROM ai_marking_record
deleted = 0
AND answer_sheet_id = #{query.answerSheetId}
AND question_no = #{query.questionNo}
AND status = #{query.status}
AND provider_name LIKE CONCAT('%', #{query.providerName}, '%')
AND protocol = #{query.protocol}
ORDER BY create_time DESC, id DESC
